class _LFUMemory:
    def __init__(self, maxsize: Optional[float] = 128, typed: bool = False):
        self.maxsize = maxsize
        self.typed = typed
        self._cache = dict()
        self._hitcount = dict()

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        key = self._make_key(*args, **kwargs)
        if key in self._cache:
            self._hitcount[key] += 1
            self._remove_oldest()
            return self._cache[key]
        else:
            self._cache[key] = func(*args, **kwargs)
            self._hitcount[key] = 0
        return self._cache[key]

    def _make_key(self, *args: Any, **kwargs: Any) -> Any:
        if self.typed:
            key = (type(args[0]), args[0])
            for arg in args[1:]:
                key += (type(arg), arg)
            for k, v in kwargs.items():
                key += (k, type(v), v)
            return key
        else:
            return (args, kwargs)

    def _remove_oldest(self) -> None:
        oldest = min(self._hitcount, key=self._hitcount.get)
        del self._hitcount[oldest]
        del self._cache[oldest]

def lfu_cache(func=None, maxsize=128, typed=False):

    if func is None:
        return partial(_LFUMemory, maxsize=maxsize, typed=typed)
    else:
        memory = _LFUMemory(maxsize, typed)
        return lambda *args, **kwargs: memory(*args, **kwargs)

