    """Gets the workspace manager. """
    workspace = cls.workspace
    return workspace_manager(workspace)

@classmethod
def plugins_manager(cls):
    return cls._plugins_manager

@classmethod
def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        raise IRValidatorException("Missing spec content")

    # Initialize dictionary to store loaded data
    spec_data = dict()

    # Load data into dictionary
    spec_data = yaml.load(spec_content)

    # Check if mandatory fields are present in spec data
    for field in cls.get_required_fields():
        if field not in spec_data:
            raise IRValidatorException(f"Missing mandatory field: {field}")

    return spec_data

@classmethod
def validate_from_file(cls, yaml_file: str):
    data = yaml.load(yaml_file)
    if data is None:
        raise ValueError(f"File {yaml_file} does not contain valid YAML data")
    if not validate_if_all_values_present(data):
        raise ValueError(f"Mandatory data is missing in file {yaml_file}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'groups' in parser_dict:
        for group in parser_dict['groups']:
            if 'include' in group:
                for include in group['include']:
                    if isinstance(include, dict):
                        self._include_groups(include)
                    else:
                        raise ValueError(f"Invalid include value: {include}")
    return parser_dict

def get_spec_defaults(self):
    for arg in self.args:
        if arg.get('default') is not None:
            arg_name = arg.get('dest')
            arg_value = arg.get('default')
            self.closure[arg_name] = arg_value

