def get_silent_args(args):
    silenced_args = []
    for arg in args:
        if arg.startswith('-'):
            silenced_args.append(arg[1:])
    return silenced_args

def validate_requires_args(args):
    if "required" not in args:
        raise ValueError("`required` argument is missing")
    if not args["required"]:
        raise ValueError("`required` argument must be True")
    return args

def validate_length_args(args):
    for arg in args:
        if len(arg) > 10:
            raise Exception(f"Argument {arg} is longer than 10 characters.")

def validate_choices_args(args):
    def is_valid_choice(choice, choices):
        if choice in choices:
            return True
        else:
            raise ValueError(f"Invalid choice: {choice}. "
                             f"Choices are: {choices}")

    for arg_name, arg_value in args.items():
        if arg_name in self.CHOICE_ARGS:
            choices = self.CHOICE_ARGS[arg_name]
            for choice in arg_value:
                is_valid_choice(choice, choices)

def get_nested_custom_and_control_args(args):
    control_args = dict()
    nested_args = dict()
    custom_args = dict()

    for arg in args:
        if arg[0][0] == '-' and arg[0][1].islower():
            control_args[arg] = args.pop(0)
        elif arg[0][0] == ':' and arg[0][1].isupper():
            custom_args[arg] = args.pop(0)
        else:
            nested_args[arg] = args.pop(0)

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    for extra_var in extra_vars:
        vars_dict[extra_var[0]] = extra_var[1]
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    for argument_name, argument_type in self.parser.arguments[parser_name].items():
        if argument_type in ("integer", "int", "float"):
            values_dict[argument_name] = argument_type(values_dict[argument_name])
        elif argument_type == "bool":
            values_dict[argument_name] = argument_type(values_dict[argument_name].lower() in ("yes", "true", "1", "on"))
        elif argument_type == "list":
            values_dict[argument_name] = argument_type(values_dict[argument_name])
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    flat_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            path = os.path.join(root, file)
            with open(path, 'r') as f:
                contents = f.read()
                for line in contents.splitlines():
                    if line.startswith(':'):
                        key, val = line[1:].split(':')
                        flat_dict[key.strip()] = val.strip()
    return flat_dict

def inject_config() -> None:
    if "CONFIG_PATH" not in os.environ:
        os.environ["CONFIG_PATH"] = "/config/config.yaml"

def strip_root(path, root):
    if path.startswith(root):
        return path[len(root):]
    raise ValueError("Path must start with given root prefix")
